const src = $('④ Set - Limpiar y validar payload').first().json;
const raw = $json.text ?? $json.output ?? '';
let d;
try { d = JSON.parse(String(raw).replace(/^```json\s*/i,'').replace(/```\s*$/,'').trim()); }
catch (e) { d = {}; }
const allowed = ['BRIEF','FREELANCER','UNKNOWN'];
const intent = allowed.includes(String(d.intent).toUpperCase()) ? String(d.intent).toUpperCase() : 'UNKNOWN';
const confidence = Math.max(0, Math.min(1, Number(d.confidence) || 0));
const risk = ['LOW','MEDIUM','HIGH'].includes(String(d.risk).toUpperCase()) ? String(d.risk).toUpperCase() : 'HIGH';
return [{ json: {
  ...src,
  session_id: src.From,
  intent, confidence, risk,
  nombre: String(d.nombre || '').slice(0,80),
  empresa: String(d.empresa || '').slice(0,80),
  reason: String(d.reason || 'Salida del router inválida → fallback').slice(0,200)
}}];

const input = $('Normalizar Triage').first().json;
const m = $input.all().map(i => i.json).find(r => r && r.session_id) ?? {};
const existe = Boolean(m.session_id);
const resumen = m.resumen_consolidado || 'Sin memoria previa';
return [{ json: {
  ...input,
  memoria_existe: existe,
  resumen_consolidado: resumen,
  estado_caso: m.estado_caso || 'NUEVO',
  datos_clave: m.datos_clave || 'Sin datos previos',
  contador_mensajes: Number(m.contador_mensajes || 0),
  // contexto que viaja al Worker (memoria M3 + mensaje actual)
  input_worker: (existe ? '[Contexto previo del contacto: ' + resumen + ']\n' : '') + input.BodyText
}}];

const ctx = $('Preparar contexto de memoria').first().json;
const w = $json ?? {};
const ok = w.status === 'success' && w.respuesta;
return [{ json: {
  ...ctx,
  status: w.status || 'error',
  worker: w.worker || 'DESCONOCIDO',
  requires_human: Boolean(w.requires_human) || !ok,
  respuesta: ok || w.status === 'escalated'
    ? w.respuesta
    : '¡Hola! Gracias por escribirnos. Un integrante del equipo de Freebag te responde a la brevedad.\n\nEquipo Freebag',
  error_message: w.error ? String(w.error.message || w.error).slice(0,200) : ''
}}];

return $input.all().map(i => {
  const n = Number(i.json.contador_mensajes || 0) + 1;
  return { json: { ...i.json, contador_mensajes: n, requiere_resumen: n >= 5, fecha_actualizacion: new Date().toISOString() } };
});

