const base = $('Actualizar contador').first().json;
const raw = $json.text ?? $json.output ?? '';
let x;
try { x = JSON.parse(String(raw).replace(/^```json\s*/i,'').replace(/```\s*$/,'').trim()); }
catch (e) { x = { asunto_principal: base.intent, puntos_clave: [base.Subject], accion_requerida: '', estado_caso: base.estado_caso }; }
return [{ json: { ...base,
  resumen_consolidado: [x.asunto_principal, ...(x.puntos_clave || []), x.accion_requerida].filter(Boolean).join(' | ').slice(0,1000),
  datos_clave: JSON.stringify({ puntos_clave: x.puntos_clave || [], accion_requerida: x.accion_requerida || '' }),
  estado_caso: x.estado_caso || base.estado_caso || 'EN_PROCESO',
  contador_mensajes: 0 } }];
